<?php
declare(strict_types=1);

/**
 * SdmFileApi
 *
 * Client for the central SDM private file storage API.
 *
 * Supported operations:
 * - Upload a file
 * - Upload generated file bytes
 * - Download a file to a temporary local file
 * - Delete a file
 *
 * Required private configuration:
 * [
 *     'endpoint' => 'https://sdm.bcp-sms.com/api/v1/files.php',
 *     'app_id'   => 'guidance',
 *     'secret'   => 'YOUR_GUIDANCE_SECRET',
 * ]
 *
 * Configure SDM_API_CONFIG_FILE with the absolute path to that
 * configuration file, located outside the public web directory.
 */

final class SdmFileApi
{
    private string $endpoint;
    private string $appId;
    private string $secret;

    private const TIMEOUT = 60;
    private const MAX_BYTES = 10485760; // 10 MB

    private const ALLOWED_TYPES = [
        'pdf'  => ['application/pdf'],
        'doc'  => [
            'application/msword',
            'application/cdfv2',
            'application/x-ole-storage',
            'application/octet-stream',
        ],
        'docx' => [
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'application/zip',
            'application/octet-stream',
        ],
        'xls'  => [
            'application/vnd.ms-excel',
            'application/cdfv2',
            'application/x-ole-storage',
            'application/octet-stream',
        ],
        'xlsx' => [
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'application/zip',
            'application/octet-stream',
        ],
        'jpg'  => ['image/jpeg'],
        'jpeg' => ['image/jpeg'],
        'png'  => ['image/png'],
    ];

    public function __construct(?string $configPath = null)
    {
        if (!function_exists('curl_init')) {
            throw new RuntimeException(
                'The PHP cURL extension is required for SDM file storage.'
            );
        }

        $configPath = $configPath
        ?? (getenv('SDM_API_CONFIG_FILE') ?: '/home/sdm.bcp-sms.com/sdm-api-config.php');

        if (!is_file($configPath) || !is_readable($configPath)) {
            throw new RuntimeException(
                'SDM API configuration file is missing or unreadable.'
            );
        }

        $config = require $configPath;

        if (!is_array($config)) {
            throw new RuntimeException(
                'The SDM API configuration must return an array.'
            );
        }

        $this->endpoint = rtrim(
            trim((string)($config['endpoint'] ?? '')),
            '/'
        );

        $this->appId = trim((string)($config['app_id'] ?? ''));
        $this->secret = trim((string)($config['secret'] ?? ''));

        if (
            !filter_var($this->endpoint, FILTER_VALIDATE_URL)
            || strtolower((string)parse_url($this->endpoint, PHP_URL_SCHEME)) !== 'https'
        ) {
            throw new RuntimeException(
                'The SDM API endpoint must be a valid HTTPS URL.'
            );
        }

        if (!preg_match('/^[a-z0-9_-]{2,50}$/', $this->appId)) {
            throw new RuntimeException('Invalid SDM application ID.');
        }

        if ($this->secret === '') {
            throw new RuntimeException('The SDM API secret is missing.');
        }
    }

    /**
     * Upload an existing local temporary file.
     *
     * Returns the API response, including file_id.
     */
    public function upload(
        string $localPath,
        string $originalName
    ): array {
        if (!is_file($localPath) || !is_readable($localPath)) {
            throw new RuntimeException('The file to upload is unavailable.');
        }

        $size = filesize($localPath);

        if ($size === false || $size < 1 || $size > self::MAX_BYTES) {
            throw new RuntimeException(
                'The file must be between 1 byte and 10 MB.'
            );
        }

        $extension = strtolower(
            pathinfo($originalName, PATHINFO_EXTENSION)
        );

        if (!isset(self::ALLOWED_TYPES[$extension])) {
            throw new RuntimeException('This file extension is not allowed.');
        }

        $mime = $this->detectMime($localPath);

        if (!in_array($mime, self::ALLOWED_TYPES[$extension], true)) {
            throw new RuntimeException(
                'The detected file type does not match the file extension.'
            );
        }

        $safeName = $this->cleanFilename($originalName);

        $curlFile = new CURLFile(
            $localPath,
            $mime,
            $safeName
        );

        return $this->request(
            [
                'action' => 'upload',
                'file' => $curlFile,
            ],
            false
        );
    }

    /**
     * Upload generated bytes, such as a generated PDF.
     *
     * A temporary file is created and deleted automatically.
     */
    public function uploadBytes(
        string $bytes,
        string $originalName
    ): array {
        if ($bytes === '' || strlen($bytes) > self::MAX_BYTES) {
            throw new RuntimeException(
                'The generated file must be between 1 byte and 10 MB.'
            );
        }

        $tempPath = tempnam(sys_get_temp_dir(), 'sdm_upload_');

        if ($tempPath === false) {
            throw new RuntimeException(
                'Could not create a temporary upload file.'
            );
        }

        try {
            $written = file_put_contents($tempPath, $bytes, LOCK_EX);

            if ($written !== strlen($bytes)) {
                throw new RuntimeException(
                    'Could not write all generated file bytes.'
                );
            }

            return $this->upload($tempPath, $originalName);
        } finally {
            if (is_file($tempPath)) {
                @unlink($tempPath);
            }
        }
    }

    /**
     * Download a file into a private temporary file.
     *
     * Returns:
     * [
     *     'path' => '/tmp/...',
     *     'filename' => 'document.pdf',
     *     'mime' => 'application/pdf',
     *     'size' => 12345
     * ]
     *
     * The caller is responsible for deleting the temporary file.
     */
    public function downloadToTemp(string $fileId): array
    {
        $this->validateFileId($fileId);

        $tempPath = tempnam(sys_get_temp_dir(), 'sdm_download_');

        if ($tempPath === false) {
            throw new RuntimeException(
                'Could not create a temporary download file.'
            );
        }

        @chmod($tempPath, 0600);

        $handle = fopen($tempPath, 'wb');

        if ($handle === false) {
            @unlink($tempPath);

            throw new RuntimeException(
                'Could not open the temporary download file.'
            );
        }

        $responseHeaders = [];
        $responseBytes = 0;

        try {
            $ch = curl_init($this->endpoint);

            if ($ch === false) {
                throw new RuntimeException(
                    'Could not initialize the SDM API connection.'
                );
            }

            curl_setopt_array($ch, [
                CURLOPT_POST => true,
                CURLOPT_POSTFIELDS => http_build_query([
                    'action' => 'download',
                    'file_id' => $fileId,
                ]),
                CURLOPT_HTTPHEADER => $this->authHeaders(),
                CURLOPT_RETURNTRANSFER => false,
                CURLOPT_FOLLOWLOCATION => false,
                CURLOPT_CONNECTTIMEOUT => 10,
                CURLOPT_TIMEOUT => self::TIMEOUT,
                CURLOPT_SSL_VERIFYPEER => true,
                CURLOPT_SSL_VERIFYHOST => 2,

                CURLOPT_HEADERFUNCTION => function ($curl, string $line)
                    use (&$responseHeaders): int {
                    $length = strlen($line);
                    $parts = explode(':', $line, 2);

                    if (count($parts) === 2) {
                        $name = strtolower(trim($parts[0]));
                        $value = trim($parts[1]);

                        $responseHeaders[$name] = $value;
                    }

                    return $length;
                },

                CURLOPT_WRITEFUNCTION => function ($curl, string $data)
                    use ($handle, &$responseBytes): int {
                    $length = strlen($data);
                    $responseBytes += $length;

                    // Stop unexpectedly large downloads.
                    if ($responseBytes > self::MAX_BYTES + 65536) {
                        return 0;
                    }

                    $written = fwrite($handle, $data);

                    return $written === false ? 0 : $written;
                },
            ]);

            $ok = curl_exec($ch);
            $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $error = curl_error($ch);

            curl_close($ch);

            fflush($handle);
            fclose($handle);
            $handle = null;

            if ($ok === false) {
                throw new RuntimeException(
                    'SDM download request failed: ' . $error
                );
            }

            if ($status !== 200) {
                $body = @file_get_contents($tempPath);
                $message = $this->extractErrorMessage(
                    is_string($body) ? $body : ''
                );

                throw new RuntimeException(
                    'SDM download failed: HTTP ' . $status .
                    '; file_id=' . $fileId .
                    '; response=' . ($message ?: 'No API error message')
                );
            }

            $mime = strtolower(trim(
                explode(';', $responseHeaders['content-type'] ?? '')[0]
            ));

            if ($mime === '' || $mime === 'application/octet-stream') {
                // Do not trust a missing or generic content type.
                throw new RuntimeException(
                    'The SDM API returned an unexpected content type.'
                );
            }

            $actualSize = filesize($tempPath);

            if ($actualSize === false || $actualSize < 1
                || $actualSize > self::MAX_BYTES) {
                throw new RuntimeException(
                    'The downloaded file size is invalid.'
                );
            }

            $filename = $this->filenameFromDisposition(
                $responseHeaders['content-disposition'] ?? '',
                $fileId
            );

            return [
                'path' => $tempPath,
                'filename' => $filename,
                'mime' => $mime,
                'size' => $actualSize,
            ];
        } catch (Throwable $e) {
            if (is_resource($handle)) {
                fclose($handle);
            }

            @unlink($tempPath);

            throw $e;
        }
    }

    /**
     * Delete a file owned by this application.
     */
    public function delete(string $fileId): array
    {
        $this->validateFileId($fileId);

        return $this->request([
            'action' => 'delete',
            'file_id' => $fileId,
        ]);
    }

    /**
     * Make an authenticated JSON or multipart request.
     */
    private function request(
        array $fields,
        bool $json = true
    ): array {
        $fields['app_id'] = $this->appId;

        $ch = curl_init($this->endpoint);

        if ($ch === false) {
            throw new RuntimeException(
                'Could not initialize the SDM API connection.'
            );
        }

        $headers = $this->authHeaders();

        if ($json) {
            $payload = http_build_query($fields);
        } else {
            $payload = $fields;
        }

        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $payload,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT => self::TIMEOUT,
            CURLOPT_FOLLOWLOCATION => false,
            CURLOPT_SSL_VERIFYPEER => true,
            CURLOPT_SSL_VERIFYHOST => 2,
        ]);

        $body = curl_exec($ch);
        $status = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $error = curl_error($ch);

        curl_close($ch);

        if ($body === false) {
            throw new RuntimeException(
                'SDM API request failed: ' . $error
            );
        }

        $decoded = json_decode($body, true);

        if ($status < 200 || $status >= 300) {
            $message = is_array($decoded)
                ? (string)($decoded['message']
                    ?? $decoded['error']
                    ?? '')
                : '';

            throw new RuntimeException(
                $message !== ''
                    ? $message
                    : 'SDM API returned HTTP ' . $status . '.'
            );
        }

        if (!is_array($decoded)) {
            throw new RuntimeException(
                'SDM API returned an invalid JSON response.'
            );
        }

        if (($decoded['success'] ?? false) !== true) {
            throw new RuntimeException(
                (string)($decoded['message']
                    ?? $decoded['error']
                    ?? 'SDM API operation was unsuccessful.')
            );
        }

        return $decoded;
    }

    private function authHeaders(): array
    {
        return [
            'Authorization: Bearer ' . $this->secret,
            'X-SDM-App-ID: ' . $this->appId,
        ];
    }

    private function detectMime(string $path): string
    {
        if (!class_exists('finfo')) {
            throw new RuntimeException(
                'The PHP fileinfo extension is required.'
            );
        }

        $finfo = new finfo(FILEINFO_MIME_TYPE);
        $mime = $finfo->file($path);

        if (!is_string($mime) || $mime === '') {
            throw new RuntimeException(
                'Could not determine the file MIME type.'
            );
        }

        return strtolower($mime);
    }

    private function validateFileId(string $fileId): void
    {
        if (!preg_match('/^[a-f0-9]{32}$/', $fileId)) {
            throw new InvalidArgumentException(
                'Invalid SDM file ID.'
            );
        }
    }

    private function cleanFilename(string $name): string
    {
        $name = basename(str_replace('\\', '/', $name));
        $name = preg_replace('/[\x00-\x1F\x7F]/', '', $name) ?? '';
        $name = trim($name);

        if ($name === '' || $name === '.' || $name === '..') {
            throw new InvalidArgumentException(
                'A valid original filename is required.'
            );
        }

        return substr($name, 0, 180);
    }

    private function filenameFromDisposition(
        string $disposition,
        string $fallback
    ): string {
        if (preg_match(
            '/filename\\s*=\\s*"([^"]+)"/i',
            $disposition,
            $matches
        )) {
            return $this->cleanFilename($matches[1]);
        }

        if (preg_match(
            "/filename\\s*=\\s*([^;]+)/i",
            $disposition,
            $matches
        )) {
            return $this->cleanFilename(trim($matches[1], " \t\"'"));
        }

        return $fallback;
    }

    private function extractErrorMessage(string $body): string
    {
        $decoded = json_decode($body, true);

        if (!is_array($decoded)) {
            return '';
        }

        return (string)($decoded['message']
            ?? $decoded['error']
            ?? '');
    }
}
